import json
from pathlib import Path
import sympy as sp

ranks = (1, 2, 3)
total_pairs = 0
total_triples = 0
for n in ranks:
    path = Path('data') / f'C_{n}_structure.json'
    data = json.loads(path.read_text(encoding='utf-8'))
    labels = data['basis']['odd'] + data['basis']['even']
    parity = data['parity']
    brackets = {}
    for record in data['structure_constants']:
        assert record['X'] in parity and record['Y'] in parity and record['Z'] in parity
        coefficient = sp.Rational(record['coeff'])
        assert coefficient != 0
        pair = (record['X'], record['Y'])
        values = brackets.setdefault(pair, {})
        assert record['Z'] not in values
        values[record['Z']] = coefficient

    def bracket_with_left(left, right_combo):
        result = {}
        for right, coefficient in right_combo.items():
            for target, value in brackets.get((left, right), {}).items():
                result[target] = result.get(target, sp.Rational(0)) + coefficient * value
                if result[target] == 0:
                    del result[target]
        return result

    for x in labels:
        for y in labels:
            sign = -1 if parity[x] * parity[y] else 1
            expected = {z: -sign * c for z, c in brackets.get((x, y), {}).items()}
            assert brackets.get((y, x), {}) == expected, ('graded antisymmetry', n, x, y)
    pair_checks = len(labels) ** 2

    for x in labels:
        for y in labels:
            for z in labels:
                jacobi = {}
                terms = (
                    (-1 if parity[x] * parity[z] else 1, x, brackets.get((y, z), {})),
                    (-1 if parity[y] * parity[x] else 1, y, brackets.get((z, x), {})),
                    (-1 if parity[z] * parity[y] else 1, z, brackets.get((x, y), {})),
                )
                for sign, left, inner in terms:
                    for target, coefficient in bracket_with_left(left, inner).items():
                        jacobi[target] = jacobi.get(target, sp.Rational(0)) + sign * coefficient
                        if jacobi[target] == 0:
                            del jacobi[target]
                assert not jacobi, ('super Jacobi', n, x, y, z, jacobi)
    triple_checks = len(labels) ** 3
    total_pairs += pair_checks
    total_triples += triple_checks
    print(f'C_{n}: PASS; basis={len(labels)}, ordered pairs={pair_checks}, ordered triples={triple_checks}, nonzero records={len(data["structure_constants"])}')
print(f'TOTAL: PASS; ordered pair checks={total_pairs}, ordered triple checks={total_triples}')
