            },
            "gamma_coefficients": compute_gamma_coefficients(n, schema1),
        },
        "metadata": {
            "generated_by": "build_C_gamma.py",
            "generation_date": generation_date or date.today().isoformat(),
            "references": [
                "docs/math/C_inhomogeneous_definition.md",
